"""Verify frozen fresh100 reviews and evaluate the preregistered relative gate."""
import json,hashlib,math,statistics
from pathlib import Path
r=Path(__file__).resolve().parents[1];summary={'schemaVersion':'translation-fresh100-summary-v1','agentReviewNonBlind':True,'humanApproved':False,'models':{}};reviews={}
for model,rid,ri,ro in [('gpt41','fresh100-gpt41-v4',2,8),('luna6','fresh100-luna6-v5',.1,.5)]:
 run=r/'runs'/rid;mb=(run/'manifest.json').read_bytes();m=json.loads(mb);v=json.loads((run/'reviews/agent-semantic-v1.json').read_text());assert hashlib.sha256(mb).hexdigest()==v['manifestHash'];assert len(v['items'])==100
 tokensIn=tokensOut=reasoning=cached=hasAlt=0;lat=[];reviews[model]={}
 for i in v['items']:
  b=(run/'responses'/(i['jobId']+'.json')).read_bytes();assert hashlib.sha256(b).hexdigest()==i['responseHash'];o=json.loads(b);assert o['outcome']=='ready';u=o['usage'];tokensIn+=u['prompt_tokens'];tokensOut+=u['completion_tokens'];reasoning+=u.get('completion_tokens_details',{}).get('reasoning_tokens',0);cached+=u.get('prompt_tokens_details',{}).get('cached_tokens',0);lat.append(o['elapsedMs']);e=o['result']['entryTranslation'];hasAlt+=bool(e and e['alternativeTexts']);reviews[model][i['jobId']]=i
 summary['models'][model]={'runId':rid,'manifestHash':v['manifestHash'],'promptFingerprint':m['promptFingerprint'],'accept':sum(i['decision']=='accept' for i in v['items']),'seriousSenseContent':sum(min(i['scores']['senseFidelity'],i['scores']['contentFidelity'])<=2 for i in v['items']),'criticalDirectionNegationModality':sum(i['criticalDirectionNegationModality'] for i in v['items']),'allDimensionsBelow3':sum(min(i['scores'].values())<=2 for i in v['items']),'score3SenseContent':sum(min(i['scores']['senseFidelity'],i['scores']['contentFidelity'])==3 for i in v['items']),'inputTokens':tokensIn,'outputTokens':tokensOut,'reasoningTokens':reasoning,'cachedTokens':cached,'knownReferenceUSD':(tokensIn*ri+tokensOut*ro)/1e6,'actualAzureInvoiceUSD':None,'latencyP50Ms':statistics.median(lat),'latencyP95Ms':sorted(lat)[94],'withAlternativeCandidates':hasAlt,'ready':100,'failed':0}
g=summary['models']['gpt41'];l=summary['models']['luna6'];summary['gatePassed']=l['accept']>g['accept'] and l['seriousSenseContent']<=g['seriousSenseContent'] and l['criticalDirectionNegationModality']<=g['criticalDirectionNegationModality'];assert set(reviews['gpt41'])==set(reviews['luna6'])
lwins=sum(reviews['luna6'][k]['decision']=='accept' and reviews['gpt41'][k]['decision']!='accept' for k in reviews['gpt41']);gwins=sum(reviews['gpt41'][k]['decision']=='accept' and reviews['luna6'][k]['decision']!='accept' for k in reviews['gpt41']);n=lwins+gwins
summary['pairedDiscordance']={'lunaOnlyAccept':lwins,'gptOnlyAccept':gwins,'exactTwoSidedBinomialP':min(1,2*sum(math.comb(n,j) for j in range(min(lwins,gwins)+1))/2**n),'limitation':'Conditional on subjective agent labels; does not remove reviewer bias or enriched sampling limitations.'}
summary['referencePriceScope']='Same2026-10-10 public uncached Standard short-context rates as full100. Translation only; no audio/review. Not confirmed Azure deployment tariff.'
print(json.dumps(summary,ensure_ascii=False,indent=2))
